INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Standardgateway immer ein Router?', 2, '[{"text": "Ja", "correct": true, "because": "Verbindet Netze"}, {"text": "Nein", "correct": false, "because": "Typischerweise Router"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das Standardgateway im Netzwerk?', 3, '[{"text": "Paketweiterleitung", "correct": true, "because": "Leitet zu anderen Netzen"}, {"text": "Adresszuweisung", "correct": false, "because": "DHCP-Aufgabe"}, {"text": "Datenkompression", "correct": false, "because": "Nicht seine Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernimmt das Standardgateway?', 5, '[{"text": "Routing zwischen Netzen", "correct": true, "because": "Verbindet Subnetze"}, {"text": "NAT", "correct": true, "because": "Oft integriert"}, {"text": "DNS-Auflösung", "correct": false, "because": "DNS-Server-Aufgabe"}, {"text": "Paketverschlüsselung", "correct": false, "because": "Andere Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Standardgateway hat eine IP im lokalen Netz. b) Es ist immer ein Server.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist meist Router"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Standardgateways?', 4, '[{"text": "IP-Adresse", "correct": false, "because": "Muss erreichbar sein"}, {"text": "Netzwerkreichweite", "correct": false, "because": "Definiert Routing"}, {"text": "CPU-Leistung", "correct": true, "because": "Sekundär für Routing"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Standardgateway mehrere Netze verbinden kann?', 2, '[{"text": "Ja", "correct": true, "because": "Routing-Funktion"}, {"text": "Nein", "correct": false, "because": "Mehrere Netze möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse wähle ich für das Standardgateway?', 3, '[{"text": "Lokale Router-IP", "correct": true, "because": "Erreichbar im Subnetz"}, {"text": "FF02::1", "correct": false, "because": "Multicast, kein Gateway"}, {"text": "127.0.0.1", "correct": false, "because": "Loopback"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat ein Standardgateway?', 5, '[{"text": "Verbindet Netze", "correct": true, "because": "Routing-Funktion"}, {"text": "Hat lokale IP", "correct": true, "because": "Erreichbar im Subnetz"}, {"text": "Weist IPs zu", "correct": false, "because": "DHCP-Aufgabe"}, {"text": "Komprimiert Daten", "correct": false, "because": "Nicht seine Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Das Standardgateway leitet Pakete weiter. b) Es ist immer ein Switch. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Switch routet nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Standardgateway?', 4, '[{"text": "IP-Adresse", "correct": false, "because": "Muss definiert sein"}, {"text": "Routing-Tabelle", "correct": false, "because": "Leitet Pakete"}, {"text": "Webserver", "correct": true, "because": "Nicht Routing-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das Standardgateway optional?', 2, '[{"text": "Nein", "correct": true, "because": "Nötig für externe Netze"}, {"text": "Ja", "correct": false, "because": "Pflicht bei Routing"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hilft mir, externe Netze zu erreichen?', 4, '[{"text": "Standardgateway", "correct": true, "because": "Leitet Pakete weiter"}, {"text": "DNS-Server", "correct": false, "because": "Nur Namensauflösung"}, {"text": "DHCP-Server", "correct": false, "because": "Nur Adresszuweisung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Standardgateway nur lokal funktioniert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Verbindet externe Netze"}, {"text": "Ja", "correct": false, "because": "Routing ist nicht lokal"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Gateway-Konfiguration?', 3, '[{"text": "Korrekte IP", "correct": true, "because": "Muss erreichbar sein"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Netzwerkabhängig"}, {"text": "DNS-Eintrag", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Standardgateway ist im Subnetz. b) Es ersetzt DNS.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DNS ist eigenständig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Standardgateway?', 5, '[{"text": "Netzwerkverbindung", "correct": true, "because": "Routing ermöglicht"}, {"text": "Paketweiterleitung", "correct": true, "because": "Zu externen Netzen"}, {"text": "IP-Zuweisung", "correct": false, "because": "DHCP-Aufgabe"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Andere Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Standardgateway unwichtig?', 3, '[{"text": "IP-Adresse", "correct": false, "because": "Muss definiert sein"}, {"text": "Routing-Fähigkeit", "correct": false, "because": "Kernfunktion"}, {"text": "Grafikschnittstelle", "correct": true, "because": "Nicht netzwerkrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein PC das Standardgateway sein?', 3, '[{"text": "Ja", "correct": true, "because": "Mit Routing-Software"}, {"text": "Nein", "correct": false, "because": "Technisch möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Standardgateway NAT braucht?', 2, '[{"text": "Nein", "correct": true, "because": "Optional, nicht Pflicht"}, {"text": "Ja", "correct": false, "because": "Routing reicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponente leitet Pakete zu einem anderen Subnetz?', 4, '[{"text": "Standardgateway", "correct": true, "because": "Routing-Funktion"}, {"text": "Switch", "correct": false, "because": "Nur Schicht 2"}, {"text": "Access Point", "correct": false, "because": "Nur WLAN"}]');
